import{_ as e,o as a,c as s,a3 as o}from"./chunks/framework.B9qR_F1m.js";const g=JSON.parse('{"title":"Install","description":"","frontmatter":{},"headers":[],"relativePath":"en/start/install.md","filePath":"en/start/install.md"}'),r={name:"en/start/install.md"};function n(i,t,l,d,h,p){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h1><p>Shardwing comes as a <strong>desktop app</strong> for Windows and macOS. It works directly with your files: open a mission, edit it, save it back to the same place.</p><div class="info custom-block"><p class="custom-block-title">German interface</p><p>The app&#39;s interface is in German for now. This manual names buttons the way they appear in the app, with the English meaning in brackets.</p></div><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><table tabindex="0"><thead><tr><th>System</th><th>File</th></tr></thead><tbody><tr><td>Windows 10/11 (x64)</td><td><code>Shardwing_&lt;version&gt;_x64-setup.exe</code></td></tr><tr><td>macOS 12 or later (Apple Silicon)</td><td><code>Shardwing_&lt;version&gt;_aarch64.dmg</code></td></tr></tbody></table><p>Both are on the <strong><a href="https://github.com/Leichtester/shardwing-releases/releases/latest" target="_blank" rel="noreferrer">latest release</a></strong>.</p><div class="warning custom-block"><p class="custom-block-title">Not code-signed yet</p><p>Your system will warn you once on the first start:</p><ul><li><strong>Windows:</strong> in SmartScreen, click &quot;More info&quot; → &quot;Run anyway&quot;.</li><li><strong>macOS:</strong> right-click the app → &quot;Open&quot; → &quot;Open&quot; again.</li></ul><p>After that, Shardwing starts normally.</p></div><p>Intel Macs are not supported at the moment.</p><h2 id="test-phase-key" tabindex="-1">Test phase: key <a class="header-anchor" href="#test-phase-key" aria-label="Permalink to &quot;Test phase: key&quot;">​</a></h2><p>While Shardwing is in its test phase, it only opens with a <strong>key</strong> (e.g. <code>K4P9-X2T7-M8QW</code>). You get it as a tester or from your squadron lead; it is the same key used to upload missions.</p><ul><li><strong>Desktop app:</strong> enter the key once on first start. The computer needs to be online for that; afterwards the app also runs offline.</li><li><strong>Browser:</strong> enter the key at <a href="https://app.shardwing.de" target="_blank" rel="noreferrer">app.shardwing.de</a> or open the link <code>…/#/zugang/&lt;key&gt;</code>. The browser remembers it for 90 days.</li><li><strong>Pilots with a mission link</strong> need no key. The link opens the app as long as the mission is on the server.</li></ul><p>The top right shows <strong>Beta · für &lt;name&gt;</strong> (licensed to), also small in the footer of every kneeboard. Please do not pass on the key or the app.</p><p>Each test build of the desktop app runs out <strong>60 days</strong> after its release. The next update keeps it going; the app offers it by itself. If a key is blocked or renewed, the app closes again on the next start with internet.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>Shardwing checks for a new version on start and every few hours after that. If there is one, a note with the changes appears <strong>at the bottom right</strong>. Nothing is installed until you click <strong>Installieren und neu starten</strong> (install and restart); if you have unsaved changes, Shardwing asks first.</p><p>Every update is signed and checked before it is installed. The app refuses unsigned packages.</p><h2 id="no-installation-in-the-browser" tabindex="-1">No installation: in the browser <a class="header-anchor" href="#no-installation-in-the-browser" aria-label="Permalink to &quot;No installation: in the browser&quot;">​</a></h2><p>Shardwing also runs in the browser (Chrome, Edge, Firefox, Safari) at <a href="https://app.shardwing.de" target="_blank" rel="noreferrer">app.shardwing.de</a>. The difference:</p><table tabindex="0"><thead><tr><th></th><th>Desktop app</th><th>Browser</th></tr></thead><tbody><tr><td>Open</td><td>dialog or drag the file into the window</td><td>dialog or drag the file into the window</td></tr><tr><td>Save</td><td><strong>to the same place</strong>, with a backup of the old file</td><td>as a download (in Chrome/Edge sometimes directly)</td></tr><tr><td>Updates</td><td>automatic</td><td>always the latest version</td></tr><tr><td>Planning together</td><td>✓</td><td>✓</td></tr></tbody></table><p>Pilots who only edit their slot in a shared mission don&#39;t need to install anything: they just open their link in the browser.</p><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to &quot;Backups&quot;">​</a></h2><p>When saving, the desktop app keeps a copy of the previous file, the last 30 per mission:</p><ul><li><strong>macOS:</strong> <code>~/Library/Application Support/de.shardwing.desktop/backups/</code></li><li><strong>Windows:</strong> in Shardwing&#39;s app data folder (<code>%APPDATA%\\de.shardwing.desktop\\backups\\</code>)</li></ul><p>Files are written through a temporary file, so even a crash never leaves half a mission behind.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>A <strong>mission (.miz)</strong> from the DCS Mission Editor. Shardwing doesn&#39;t create missions from scratch (yet); it adds to existing ones.</li><li>For cartridges: an <strong>F-16C</strong> or <strong>F/A-18C</strong> in the mission. You still see every other aircraft with its route, radios, loadout and lineup card.</li><li>Internet for the map tiles. Everything else runs locally on your computer.</li></ul><p><strong>Next:</strong> <a href="./first-mission">Your first mission in 5 minutes →</a></p>',27)])])}const u=e(r,[["render",n]]);export{g as __pageData,u as default};
